function settleTiles(row: string): string {
  let cur = row.split("");
  while (true) {
    const next = [...cur];
    let changed = false;
    for (let i = 0; i < cur.length; i++) {
      if (cur[i] !== ".") continue;
      const fromLeft = i > 0 && cur[i - 1] === "R";
      const fromRight = i < cur.length - 1 && cur[i + 1] === "L";
      if (fromLeft && !fromRight) { next[i] = "R"; changed = true; }
      if (fromRight && !fromLeft) { next[i] = "L"; changed = true; }
    }
    if (!changed) return cur.join("");
    cur = next;
  }
}

