function settleTiles(row: string): string {
  const s = ("L" + row + "R").split("");
  let prev = 0;
  for (let i = 1; i < s.length; i++) {
    if (s[i] === ".") continue;
    if (s[prev] === s[i]) {
      for (let k = prev + 1; k < i; k++) s[k] = s[i];
    } else if (s[prev] === "R") {
      // R ... L: fronts meet in the middle
      for (let lo = prev + 1, hi = i - 1; lo < hi; lo++, hi--) {
        s[lo] = "R";
        s[hi] = "L";
      }
    }
    prev = i;
  }
  return s.slice(1, -1).join("");
}

