        s = list("L" + row + "R")
        prev = 0
        for i in range(1, len(s)):
            if s[i] == ".":
                continue
            if s[prev] == s[i]:
                for k in range(prev + 1, i):
                    s[k] = s[i]
            elif s[prev] == "R":
                lo, hi = prev + 1, i - 1
                while lo < hi:
                    s[lo], s[hi] = "R", "L"
                    lo += 1
                    hi -= 1
            prev = i
        return "".join(s[1:-1])

